function Contact(){const [form,setForm]=useState({name:'',email:'',organization:'',topic:contactTopics[0],message:'',consent:false}),[busy,setBusy]=useState(false),[error,setError]=useState(''),[done,setDone]=useState('');async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)}),d:any=await r.json();if(!r.ok)throw new Error(d.error);setDone(d.message)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}return <div className="wrap page narrow"><PageHead label="WE’D LOVE TO HEAR FROM YOU" title="Contact SwIRL">Questions about curriculum, licensing, refunds, or your data? Send the SwIRL team a note.</PageHead>{done?<div className="status-panel"><CheckCircle/><h2>Thank you.</h2><p>{done}</p><a className="button primary" href="/curriculum">Explore curriculum</a></div>:<form className="request-form" onSubmit={e=>void submit(e)}><div className="form-grid"><label>Your name<input required maxLength={100} autoComplete="name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Email address<input required type="email" maxLength={254} autoComplete="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label>Organization <span>(optional)</span><input maxLength={160} value={form.organization} onChange={e=>setForm({...form,organization:e.target.value})}/></label><Choice label="Topic" value={form.topic} onChange={topic=>setForm({...form,topic})} options={contactTopics.map(t=>({value:t,label:t}))}/></div><label>Message<textarea required rows={6} maxLength={3000} value={form.message} onChange={e=>setForm({...form,message:e.target.value})}/></label><div className="consent"><Checkbox id="contact-consent" checked={form.consent} onCheckedChange={v=>setForm({...form,consent:v===true})}/><label htmlFor="contact-consent">I am an adult and agree to SwIRL storing this message so the team can reply. I have not included student information.</label></div>{error&&<p className="error" role="alert">{error}</p>}<button className="button primary" disabled={busy||!form.consent}>{busy?'Sending…':'Send message'}<ArrowRight size={17}/></button></form>}</div>}
